package dev.arabicgames.phone;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
import java.security.*;import java.security.cert.Certificate;import java.io.*;import java.util.*;import javax.crypto.spec.SecretKeySpec;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class AiKeyStorageTest {
 public static final class MemoryKeyStore extends KeyStoreSpi {
  private static final Key key=new SecretKeySpec(new byte[32],"AES");
  public Key engineGetKey(String a,char[] p){return key;}public Certificate[] engineGetCertificateChain(String a){return null;}public Certificate engineGetCertificate(String a){return null;}public Date engineGetCreationDate(String a){return new Date();}public void engineSetKeyEntry(String a,Key k,char[] p,Certificate[] c){}public void engineSetKeyEntry(String a,byte[] k,Certificate[] c){}public void engineSetCertificateEntry(String a,Certificate c){}public void engineDeleteEntry(String a){}public Enumeration<String> engineAliases(){return Collections.enumeration(List.of("ArabicGamesAiKeys"));}public boolean engineContainsAlias(String a){return true;}public int engineSize(){return 1;}public boolean engineIsKeyEntry(String a){return true;}public boolean engineIsCertificateEntry(String a){return false;}public String engineGetCertificateAlias(Certificate c){return null;}public void engineStore(OutputStream s,char[] p){}public void engineLoad(InputStream s,char[] p){}
 }
 @Before public void setup(){Provider provider=new Provider("TestPhoneKeyStore",1.0,"Test-only AES storage"){ };provider.put("KeyStore.AndroidKeyStore",MemoryKeyStore.class.getName());Security.insertProviderAt(provider,1);AiPreferences.clear(RuntimeEnvironment.getApplication());}
 @After public void cleanup(){AiPreferences.clear(RuntimeEnvironment.getApplication());Security.removeProvider("TestPhoneKeyStore");}
 @Test public void durableKeysSurviveSessionResetAndProviderChanges()throws Exception {var c=RuntimeEnvironment.getApplication();AiPreferences.save(c,"deepl","auto","RDR2","deep-key:fx",true);String encrypted=AiPreferences.prefs(c).getString("deepl.key","");assertFalse(encrypted.contains("deep-key"));AiPreferences.clearSession();assertEquals("deep-key:fx",AiPreferences.read(c).key);AiPreferences.save(c,"gemini","gemini-3.5-flash-lite","RDR2","gemini-key",true);assertEquals("deep-key:fx",AiPreferences.key(c,"deepl"));AiPreferences.save(c,"deepl","auto","RDR2","",true);assertEquals("deep-key:fx",AiPreferences.read(c).key);assertEquals(encrypted,AiPreferences.prefs(c).getString("deepl.key",""));}
 @Test public void explicitSavePromotesTemporaryKeyAndCleansClipboardMarkers()throws Exception {var c=RuntimeEnvironment.getApplication();AiPreferences.useForSession("deepl","auto","RDR2","\u200f temporary-key:fx\u202c",true,false);AiPreferences.save(c,"deepl","auto","RDR2","",true);AiPreferences.clearSession();assertEquals("temporary-key:fx",AiPreferences.read(c).key);}
}
